#!/usr/bin/env python3
"""
Round 182b (culprits), 5 October 2026. Needs round 181b.

The Glass house basemap taken out.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 182b (5 October)\n\nNeeds round 181b (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Owner: remove the Glass house basemap. Taken out whole: its block\n  (GLASS, glassPaintPixels, the glasspaint protocol, its layers, sky and\n  switch), its menu line, THEMED_NAMES.glass and the \"glass\" checks in\n  themedWhich and themedSync. Rounds 180b (Aqua) and 181b (Glass house)\n  leave nothing behind; the menu is back to Jurassic, Atlas, Woodlands,\n  Bioluminescent, Earth at Night, Hell, Standard.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round182b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 181b" not in h.read_text(encoding="utf-8"):
        sys.exit("round182b: round 181b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round182b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round182b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round182b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
